#include <bits/stdc++.h>
using namespace std;
using ll=long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin>>t;
    while(t--){
        int n;
        cin>>n;
        vector<ll> a(3*n);
        for( auto &x:a)
            cin>>x;
        sort(a.rbegin(),a.rend());
        vector<ll>pref(3*n+1,0);
        for(int i=0; i<3*n; i++)
            pref[i+1] =pref[i]+a[i];
        ll ans= 0;
        for(int A=0;A<=n; A++){
            int low =0;
            int high =n-A;
            while(low<high){
                int B = (low+high) /2;
                int i=A+2*B;
                int k=3*n-2*A-B;
                ll diff =a[i]+a[i+1]-3*a[k-1];
                if(diff>=0)
                    low =B+1;
                    
                else
                    high =B;
            }
                            
            int B=low;
            ll cur =2LL*pref[A] +pref[A+2*B]+3LL*pref[3*n-2*A-B];
            ans =max(ans,cur);
        }
        cout<<ans<<endl;
        
    }
    return 0;
    
